        args::Command::Install => {
            config::install_shell_function();
            process::exit(0);
        }
        args::Command::WriteDefaultConf { path } => {
            config::write_default_config(&path);
            process::exit(0);
        }
        args::Command::Browse { path, .. } => {
            // For now, just exit for non-interactive modes
            process::exit(0);
        }
    }
}
