pub fn build_tree(root: &Path) -> Result<Vec<TreeNode>, std::io::Error> {
    let mut nodes = Vec::new();

    if let Ok(entries) = fs::read_dir(root) {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();
                let name = path
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("")
                    .to_string();
                let is_dir = path.is_dir();

                nodes.push(TreeNode {
                    path: path.to_string_lossy().to_string(),
                    name,
                    is_dir,
                });
            }
        }
    }

    Ok(nodes)
}
