use std::path::PathBuf;

#[derive(Debug, Clone)]
pub enum Command {
    Help,
    Version,
    Install,
    PrintShellFunction { shell: String },
    WriteDefaultConf { path: PathBuf },
    SetInstallState { state: String },
    Browse { path: Option<PathBuf>, flags: BrowseFlags },
    Listen { socket: String },
}

#[derive(Debug, Clone, Default)]
pub struct BrowseFlags {
    pub dates: Option<bool>,
    pub only_folders: Option<bool>,
    pub show_git_info: Option<bool>,
    pub hidden: Option<bool>,
    pub git_ignored: Option<bool>,
    pub permissions: Option<bool>,
    pub sizes: Option<bool>,
    pub trim_root: Option<bool>,
    pub show_root_fs: bool,
    pub max_depth: Option<usize>,
    pub sort_by: Option<SortBy>,
    pub color: String,
    pub height: Option<usize>,
}

#[derive(Debug, Clone)]
pub enum SortBy {
    Count,
    Date,
    Size,
    Type,
    TypeDirsFirst,
    TypeDirsLast,
}

pub fn parse_args(args: Vec<String>) -> ParsedArgs {
    let mut command = Command::Browse {
        path: None,
        flags: BrowseFlags::default(),
    };
    let mut i = 1;
    let mut path: Option<PathBuf> = None;
    let mut flags = BrowseFlags {
        color: "auto".to_string(),
        ..Default::default()
    };

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "--help" => {
                command = Command::Help;
                i += 1;
                continue;
            }
            "--version" | "-V" => {
                command = Command::Version;
                i += 1;
                continue;
            }
            "--install" => {
                command = Command::Install;
                i += 1;
                continue;
            }
            "--print-shell-function" => {
                i += 1;
                if i < args.len() {
                    let shell = args[i].clone();
                    command = Command::PrintShellFunction { shell };
                    i += 1;
                    continue;
                }
            }
            "--write-default-conf" => {
                i += 1;
                if i < args.len() {
                    let path = PathBuf::from(&args[i]);
                    command = Command::WriteDefaultConf { path };
                    i += 1;
                    continue;
                }
            }
            "--set-install-state" => {
                i += 1;
                if i < args.len() {
                    let state = args[i].clone();
                    command = Command::SetInstallState { state };
                    i += 1;
                    continue;
                }
            }
            "--listen" => {
                i += 1;
                if i < args.len() {
                    let socket = args[i].clone();
                    command = Command::Listen { socket };
                    i += 1;
                    continue;
                }
            }
            "--listen-auto" => {
                let socket = format!("/tmp/broot-{}", uuid_v4());
                command = Command::Listen { socket };
                i += 1;
                continue;
            }
            "-d" | "--dates" => flags.dates = Some(true),
            "-D" | "--no-dates" => flags.dates = Some(false),
            "-f" | "--only-folders" => flags.only_folders = Some(true),
            "-F" | "--no-only-folders" => flags.only_folders = Some(false),
            "-g" | "--show-git-info" => flags.show_git_info = Some(true),
            "-G" | "--no-show-git-info" => flags.show_git_info = Some(false),
            "-h" | "--hidden" => flags.hidden = Some(true),
            "-H" | "--no-hidden" => flags.hidden = Some(false),
            "-i" | "--git-ignored" => flags.git_ignored = Some(true),
            "-I" | "--no-git-ignored" => flags.git_ignored = Some(false),
            "-p" | "--permissions" => flags.permissions = Some(true),
            "-P" | "--no-permissions" => flags.permissions = Some(false),
            "-s" | "--sizes" => flags.sizes = Some(true),
            "-S" | "--no-sizes" => flags.sizes = Some(false),
            "-t" | "--trim-root" => flags.trim_root = Some(true),
            "-T" | "--no-trim-root" => flags.trim_root = Some(false),
            "-w" | "--whale-spotting" => {
                flags.sizes = Some(true);
                flags.hidden = Some(true);
                flags.git_ignored = Some(true);
                flags.sort_by = Some(SortBy::Size);
            }
            "--show-root-fs" => flags.show_root_fs = true,
            "--sort-by-count" => flags.sort_by = Some(SortBy::Count),
            "--sort-by-date" => flags.sort_by = Some(SortBy::Date),
            "--sort-by-size" => flags.sort_by = Some(SortBy::Size),
