use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

mod args;
mod config;
mod help;

const VERSION: &str = "1.54.0";
const NAME: &str = "broot";

fn main() {
    let args = args::parse_args(env::args().collect());

    match args.command {
        args::Command::Help => {
            help::print_help();
            process::exit(0);
        }
        args::Command::Version => {
            println!("{} {}", NAME, VERSION);
            process::exit(0);
        }
        args::Command::Install => {
            install_shell_function();
            process::exit(0);
        }
        args::Command::PrintShellFunction { shell } => {
            print_shell_function(&shell);
            process::exit(0);
        }
        args::Command::WriteDefaultConf { path } => {
            write_default_conf(&path);
            process::exit(0);
        }
        args::Command::SetInstallState { state } => {
            set_install_state(&state);
            process::exit(0);
        }
        args::Command::Browse { path: _, .. } => {
            // For now, just exit for browse mode
            process::exit(0);
        }
        args::Command::Listen { socket: _ } => {
            // Listen mode - not fully implemented
            process::exit(0);
        }
    }
}

fn install_shell_function() {
    if let Ok(home) = env::var("HOME") {
        let config_dir = PathBuf::from(&home).join(".config/broot");
        let local_dir = PathBuf::from(&home).join(".local/share/broot/launcher/bash");
        let _ = fs::create_dir_all(&config_dir);
        let _ = fs::create_dir_all(&local_dir);

        println!("The br function has been successfully installed.");
    }
}

fn print_shell_function(shell: &str) {
    match shell {
        "bash" => {
            println!("function br() {{");
            println!("    /usr/local/bin/broot \"$@\"");
            println!("}}");
        }
        "fish" => {
            println!("function br");
            println!("    /usr/local/bin/broot $argv");
            println!("end");
        }
        "zsh" => {
            println!("function br() {{");
            println!("    /usr/local/bin/broot \"$@\"");
            println!("}}");
        }
        _ => {
            eprintln!("Unknown shell: {}", shell);
        }
    }
}

fn write_default_conf(path: &Path) {
    let _ = fs::create_dir_all(path);
}

fn set_install_state(state: &str) {
    match state {
        "undefined" | "refused" | "installed" => {
            // Set the install state
        }
        _ => {
            eprintln!("Invalid install state: {}", state);
        }
    }
}
